  internal static object Invoke(Type type,string name,params object[] args)=>RunRiskBindingTests.Call(type,name,args);
  [Test] public void ExplicitApprovedPolicySeparatesHitAndAttackPhases(){var type=typeof(BDirectAttackBasicLoop).Assembly.GetType("LastRail.Battle.BWaveBoardingPolicy");Assert.NotNull(type,"Missing approved v06 typed boarding policy");var p=Invoke(type,"ForDepth",1);Assert.AreEqual(4,type.GetProperty("AliveCap").GetValue(p));Assert.AreEqual(600,type.GetProperty("EntranceMilliseconds").GetValue(p));Assert.AreEqual(800,type.GetProperty("ApproachMilliseconds").GetValue(p));Assert.AreEqual(200,type.GetProperty("AttachedMilliseconds").GetValue(p));Assert.AreEqual(1800,type.GetProperty("ClimbingMilliseconds").GetValue(p));}
  [Test] public void WaveRosterUsesExplicitNativeIntakeWithoutQuietlyRelaxingOldFiveCap(){Assert.NotNull(typeof(BDirectAttackInput).GetMethod("ReadWaveRuntime"),"Missing explicit wave native input version");var t=typeof(BDirectAttackBasicLoopTests);var packet=(JObject)t.GetMethod("Packet",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{1});var entities=(JArray)packet["entities"];var enemy=entities.Single(x=>(string)x["id"]=="enemy");for(int n=1;n<6;n++){var e=enemy.DeepClone();e["id"]="enemy"+n;entities.Add(e);}var error=Assert.Throws<TargetInvocationException>(()=>t.GetMethod("Input",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{packet}));Assert.IsInstanceOf<ArgumentException>(error.InnerException,"Original five-enemy input must stay restricted");}
  static object Private(string method,params object[] args)=>typeof(BDirectAttackBasicLoopTests).GetMethod(method,BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,args);
  internal static BScoutGunnerNodeSnapshot Source(int index=0){var p=BScoutGunnerSourceTests.Sample(index);return BScoutGunnerNodeSnapshot.Read(p,BScoutGunnerSourceTests.Trust(p));}
  internal static JObject WavePacket(BScoutGunnerNodeSnapshot source){var p=(JObject)Private("Packet",1);p["version"]=BDirectAttackInput.WaveRuntimeVersion;p["provenance"]="LOCAL_VERIFIED_WAVE_SOURCE_NOT_OPERATING_START";p["waveSourceHash"]=source.Capture()["sourceHash"].DeepClone();var original=(JObject)((JArray)p["entities"]).Single(x=>(string)x["id"]=="enemy").DeepClone();var entities=new JArray(((JArray)p["entities"]).Where(x=>(string)x["kind"]!="LOCAL_ENEMY").Select(x=>x.DeepClone()));foreach(var instance in source.Waves.SelectMany(w=>w.Instances)){var e=(JObject)original.DeepClone();var type=((JArray)source.Capture()["definition"]["types"]).Single(t=>(string)t["definitionId"]==instance.DefinitionId);e["id"]=instance.InstanceId;e["definitionId"]=instance.DefinitionId;e["maxHp"]=(int)instance.Hp;e["attack"]=type["rawAction"]["value"].DeepClone();e["defense"]=new JObject{["numerator"]="53",["denominator"]="1"};e["basicIntervalMicroseconds"]=(long)type["basicPeriodMs"]*1000;e["allowedTargets"]=new JArray("OPERATOR");foreach(string name in new[]{"attackSources","defenseSources","effects","weakening","penetration"})e[name]=new JArray();e["reductions"]=new JObject{["equipment"]=new JArray(),["guardStance"]=new JArray(),["independent"]=new JArray()};entities.Add(e);}p["entities"]=entities;p["geometry"]=new JArray();p["initialShields"]=new JArray();return p;}
  internal static BDirectAttackInput ReadWave(JObject p,BScoutGunnerNodeSnapshot source,JObject localProfile=null){var owned=localProfile??(JObject)Private("Owned");owned["accountId"]=source.Capture()["origin"]["accountId"].DeepClone();var definition=(CombatDefinitionIndex)Private("Definition");var formation=new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,((JArray)p["formation"]["slots"]).Select(x=>new BCombatSlot((string)x["carriageId"],(string)x["operatorId"])));p["ownedProfileHash"]=BDirectAttackInput.Digest(owned);return BDirectAttackInput.ReadWaveRuntime(p,BDirectAttackInput.Digest(p),formation,owned,BDirectAttackInput.Digest(owned),definition,source);}
  [TestCase(0)][TestCase(1)][TestCase(2)] public void FullNodePlannedRosterKeepsHpInOriginalNativeSession(int index){var source=Source(index);var p=WavePacket(source);var input=ReadWave(p,source);var session=new BDirectAttackSession(input,1000);Assert.AreEqual(source.Waves.Sum(w=>w.Count),((JArray)input.Capture()["entities"]).Count(e=>(string)e["kind"]=="LOCAL_ENEMY"));Assert.Greater(source.Waves.Sum(w=>w.Count),5);foreach(var actor in source.Waves.SelectMany(w=>w.Instances))Assert.AreEqual((int)actor.Hp,session.Hp(actor.InstanceId));Assert.AreEqual(1,((JArray)input.Capture()["entities"]).Where(e=>(string)e["kind"]=="LOCAL_ENEMY").Select(e=>(int)e["slot"]).Distinct().Count(),"Same carriage does not become fake different slots");Assert.IsFalse(input.OperationallyExecutable);}
  [TestCase("hp")][TestCase("source")][TestCase("oldVersion")]
  public void WaveIntakeRejectsWrongOriginalSourceAndLegacyVersion(string fault){var source=Source();var p=WavePacket(source);if(fault=="hp")((JArray)p["entities"]).First(e=>(string)e["kind"]=="LOCAL_ENEMY")["maxHp"]=1;if(fault=="source")p["waveSourceHash"]=new string('f',64);if(fault=="oldVersion")p["version"]=BDirectAttackInput.Version;Assert.Throws<ArgumentException>(()=>ReadWave(p,source));}
  internal static BDirectAttackBasicLoopBinding WaveBinding(BScoutGunnerNodeSnapshot source,JObject packet=null,JObject localProfile=null,string type="BCB01"){var input=ReadWave(packet??WavePacket(source),source,localProfile);var b=(JObject)Private("BindingPacket",input,type,5,"ENEMY");b["version"]="unity.combat-b.wave-buff-binding-local.v1.20261004";b["departure"]["accountId"]=source.Capture()["origin"]["accountId"].DeepClone();b["targetCategories"]=new JArray(source.Waves.SelectMany(w=>w.Instances).Select(i=>new JObject{["targetId"]=i.InstanceId,["category"]="ENEMY"}));var composition=new BDirectAttackBuffBinding(input,(BCarriageBuffDefinitions)Private("Defs"),b,BDirectAttackInput.Digest(b));var route=new JObject{["version"]="unity.combat-b.wave-loop-binding-local.v1.20261004",["provenance"]="BOUNDED_LOCAL_NOT_FULL_RUN",["compositionHash"]=composition.OriginalHash,["targets"]=new JArray(source.Waves.SelectMany(w=>w.Instances).Select(i=>new JObject{["sourceId"]=i.InstanceId,["targetId"]="op_mira"}).Concat(new[]{new JObject{["sourceId"]="op_mira",["targetId"]=source.Waves[0].Instances[0].InstanceId}}))};return new BDirectAttackBasicLoopBinding(composition,route,BDirectAttackInput.Digest(route));}
  [Test] public void WaveBindingsDoNotRequireInventedGeometryToDescribeMissingRoutes(){var b=WaveBinding(Source(2));Assert.Greater(((JArray)b.Capture()["targets"]).Count,16);Assert.IsTrue(b.Composition.Attack.OperationallyExecutable==false);}
