  static (BDirectAttackBasicLoopBinding binding,BWaveBoardingLocalPaths paths) TwoOperatorFixture(BScoutGunnerNodeSnapshot source,bool matching=false,bool boundaryAttack=false){var p=WavePacket(source);p["stepTimeSpanTicks"]=100000;var form=new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,new[]{new BCombatSlot("car0","op_mira"),new BCombatSlot("car1","op_eve")});p["formation"]=form.Capture();var car=((JArray)p["entities"]).Single(x=>(string)x["id"]=="car0").DeepClone();car["id"]="car1";car["definitionId"]="LOCAL_ORIGINAL_car1";car["slot"]=1;((JArray)p["entities"]).Add(car);var eve=((JArray)BEveBasicTests.Packet()["entities"]).Single(x=>(string)x["id"]=="op_eve").DeepClone();eve["slot"]=1;((JArray)p["entities"]).Add(eve);JObject profile=null;if(matching){int ordinal=0;foreach(var e in ((JArray)p["entities"]).Where(x=>(string)x["kind"]=="LOCAL_ENEMY"))e["slot"]=ordinal++%2;var geometry=new JArray();foreach(var e in ((JArray)p["entities"]).Where(x=>(string)x["kind"]=="LOCAL_ENEMY"))foreach(var op in new[]{"op_mira","op_eve"})geometry.Add(new JObject{["sourceId"]=op,["targetId"]=e["id"].DeepClone(),["sourceSlot"]=op=="op_mira"?0:1,["targetSlot"]=e["slot"].DeepClone(),["distanceMm"]=1000,["maximumDistanceMm"]=1800,["observedTick"]=0,["validUntilTick"]=100000,["eligible"]=true});p["geometry"]=geometry;}if(boundaryAttack){profile=LocalBoundaryAttackProfile(p);var stats=((JArray)profile["operators"]).Single(x=>(string)x["operatorId"]=="op_eve")["permanentStats"];stats["attack"]=new JObject{["numerator"]="500",["denominator"]="1"};((JArray)p["entities"]).Single(x=>(string)x["id"]=="op_eve")["attack"]=stats["attack"].DeepClone();}var input=ReadWave(p,source,profile);var old=WaveBinding(source);var buff=old.Composition.Capture();buff["attackInputHash"]=input.OriginalHash;var second= buff["departure"]["cars"][0].DeepClone();second["slot"]=1;second["instanceId"]="car1";second["occupant"]["operatorId"]="op_eve";((JArray)buff["departure"]["cars"]).Add(second);var state=buff["initial"]["cars"][0].DeepClone();state["slot"]=1;((JArray)buff["initial"]["cars"]).Add(state);var composition=new BDirectAttackBuffBinding(input,(BCarriageBuffDefinitions)Private("Defs"),buff,BDirectAttackInput.Digest(buff));var route=old.Capture();route["compositionHash"]=composition.OriginalHash;if(matching)foreach(var r in (JArray)route["targets"]){var actor=((JArray)p["entities"]).Single(x=>(string)x["id"]==(string)r["sourceId"]);if((string)actor["kind"]=="LOCAL_ENEMY")r["targetId"]=(int)actor["slot"]==0?"op_mira":"op_eve";}var binding=new BDirectAttackBasicLoopBinding(composition,route,BDirectAttackInput.Digest(route));var paths=Paths(input).Capture();var secondPath=paths["carriages"][0].DeepClone();secondPath["slot"]=1;secondPath["carriageId"]="car1";secondPath["left"]["socketId"]="left1";secondPath["right"]["socketId"]="right1";((JArray)paths["carriages"]).Add(secondPath);var local=BWaveBoardingLocalPaths.Read(paths,BDirectAttackInput.Digest(paths),input);return(binding,local);}
  [Test] public void DynamicAssignmentCannotClaimRoofWithoutMatchingGeometryObservation(){var source=Source();var fixture=TwoOperatorFixture(source);var s=BDirectAttackBasicLoop.CreateWaveRuntime(fixture.binding,source,fixture.paths,10000);Time(s,"roof",3400);var assigned=Lives(s).Where(x=>(int)x["slot"]==1).ToArray();Assert.Greater(assigned.Length,0);Assert.IsTrue(assigned.All(x=>(string)x["phase"]=="GeometryPending"));Assert.IsTrue(assigned.All(x=>!(bool)x["attackEligible"]));}
  [TestCase(6)][TestCase(8)][TestCase(9)][TestCase(12)][TestCase(13)][TestCase(16)]
  public void OriginalProducerCountEndpointsUseOneNativeHpPool(int count){var archive=JObject.Parse(System.IO.File.ReadAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261003/WaveBoarding/original-boundary-sources.json"));var row=(JObject)((JArray)archive["samples"]).Single(x=>(int)x["count"]==count);var p=(JObject)row["source"];var source=BScoutGunnerNodeSnapshot.Read(p,(JObject)row["trustedOriginal"]);Assert.AreEqual(count,source.Waves[0].Count);var input=ReadWave(WavePacket(source),source);var native=new BDirectAttackSession(input,1000);foreach(var actor in source.Waves.SelectMany(w=>w.Instances))Assert.AreEqual((int)actor.Hp,native.Hp(actor.InstanceId));}
  static JObject Side(string id)=>new JObject{["socketId"]=id,["approachPathMm"]=new JArray(new JArray(0,0,0),new JArray(100,0,0)),["climbPathMm"]=new JArray(new JArray(100,0,0),new JArray(100,100,0))};
  internal static BWaveBoardingLocalPaths Paths(BDirectAttackInput input){var p=new JObject{["version"]=BWaveBoardingLocalPaths.Version,["provenance"]="EXPLICIT_LOCAL_GRAPH_FIXTURE_NOT_ORDINARY_RUNTIME",["inputHash"]=input.OriginalHash,["carriages"]=new JArray(new JObject{["carriageId"]="car0",["slot"]=0,["left"]=Side("left"),["right"]=Side("right")})};return BWaveBoardingLocalPaths.Read(p,BDirectAttackInput.Digest(p),input);}
  static JArray Lives(BDirectAttackBasicLoop s)=>(JArray)s.Capture()["boarding"]["lives"];
  static void Time(BDirectAttackBasicLoop s,string id,int ms)=>s.Advance(id,ms*10000L,ms);
  internal static JObject HitPacket(BScoutGunnerNodeSnapshot source,bool operators,bool enemies){var p=WavePacket(source);var original=(JObject)Private("Packet",1);var geoms=new JArray();foreach(var actor in source.Waves.SelectMany(w=>w.Instances)){if(operators){var g=((JArray)original["geometry"]).Single(x=>(string)x["sourceId"]=="op_mira").DeepClone();g["targetId"]=actor.InstanceId;g["validUntilTick"]=1000000;geoms.Add(g);}if(enemies){var g=((JArray)original["geometry"]).Single(x=>(string)x["sourceId"]=="enemy"&&(string)x["targetId"]=="op_mira").DeepClone();g["sourceId"]=actor.InstanceId;g["validUntilTick"]=1000000;geoms.Add(g);}}p["geometry"]=geoms;return p;}
  [Test] public void EntranceAndUnregisteredActorsRejectNativeDamageAtomically(){var source=Source();var b=WaveBinding(source,HitPacket(source,true,false));var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,Paths(b.Composition.Attack),10000);var first=source.Waves[0].Instances[0];var future=source.Waves[1].Instances[0];Time(s,"early",599);var before=s.Capture();Assert.Throws<InvalidOperationException>(()=>s.ApplyWaveBasic("tooEarly","op_mira",first.InstanceId,1));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));Assert.Throws<InvalidOperationException>(()=>s.ApplyWaveBasic("future","op_mira",future.InstanceId,0));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));Time(s,"ready",1);Assert.Less(s.Hp(first.InstanceId),(int)first.Hp);Assert.AreEqual((int)future.Hp,s.Hp(future.InstanceId));}
  [Test] public void NativeHpClearsTwoWavesWithExactGapAndNoSocketDoubleReturn(){var source=Source();var p=HitPacket(source,true,false);p["stepTimeSpanTicks"]=100000;var local=LocalBoundaryAttackProfile(p);foreach(var g in (JArray)p["geometry"])g["observedTick"]=140;var b=WaveBinding(source,p,local);var paths=Paths(b.Composition.Attack);var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,paths,10000);for(int i=0;i<30&&s.Outcome=="RUNNING";i++)Time(s,"batch"+i,10000);Assert.AreEqual("VICTORY",s.Outcome);foreach(var actor in source.Waves.SelectMany(w=>w.Instances))Assert.AreEqual(0,s.Hp(actor.InstanceId));var events=(JArray)s.Capture()["boarding"]["events"];Assert.Greater(events.Count(e=>(string)e["kind"]=="SOCKET_RETURN_DEATH"),0);Assert.IsTrue(events.Where(e=>((string)e["kind"]).StartsWith("SOCKET_RETURN")).All(e=>e["socketId"].Type==JTokenType.String));foreach(var actor in source.Waves.SelectMany(w=>w.Instances)){Assert.AreEqual(1,events.Count(e=>(string)e["instanceId"]==actor.InstanceId&&(string)e["kind"]=="UNREGISTER_DEATH"));Assert.AreEqual(2,(long)Lives(s).Single(x=>(string)x["id"]==actor.InstanceId)["generation"]);}long firstClear=(long)((JArray)s.Capture()["waveEntry"]["events"]).First(e=>(string)e["kind"]=="WAVE_CLEAR")["tick"];long secondEntry=(long)events.First(e=>(string)e["instanceId"]==source.Waves[1].Instances[0].InstanceId&&(string)e["kind"]=="REGISTER")["tick"];Assert.AreEqual(200,secondEntry-firstClear);var restored=BDirectAttackBasicLoop.RestoreWaveRuntime(s.Capture(),BDirectAttackInput.Digest(s.Capture()),b,source,paths,10000);Assert.AreEqual("VICTORY",restored.Outcome);}
  [Test] public void WaitingSocketIsTargetableWithoutAttackEligibility(){var source=Source();var b=WaveBinding(source,HitPacket(source,false,false));var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,Paths(b.Composition.Attack),10000);Time(s,"waiting",1400);Assert.AreEqual(2,Lives(s).Count(x=>(string)x["phase"]=="WaitingSocket"));Assert.IsTrue(Lives(s).Take(4).All(x=>(bool)x["targetable"]));Assert.IsTrue(Lives(s).Take(4).All(x=>!(bool)x["attackEligible"]));}
  internal static BDirectAttackBasicLoopBinding ManualOperators(BDirectAttackBasicLoopBinding b){var route=b.Capture();foreach(var row in ((JArray)route["targets"]).Where(x=>(string)x["sourceId"]=="op_mira").ToArray())row.Remove();return new BDirectAttackBasicLoopBinding(b.Composition,route,BDirectAttackInput.Digest(route));}
  internal static JObject LocalBoundaryAttackProfile(JObject packet){var profile=(JObject)Private("Owned");var attack=new JObject{["numerator"]="500",["denominator"]="1"};((JArray)profile["operators"]).Single(x=>(string)x["operatorId"]=="op_mira")["permanentStats"]["attack"]=attack.DeepClone();((JArray)packet["entities"]).Single(x=>(string)x["id"]=="op_mira")["attack"]=attack.DeepClone();((JArray)packet["sourceEvidence"]).Add(new JObject{["sourceId"]="EXPLICIT_LOCAL_HP_LIFETIME_BOUNDARY_PROFILE_NOT_GAME_BALANCE_OR_OPERATING_PROFILE",["sha256"]=BDirectAttackInput.Digest(profile).Substring(7)});return profile;}
  [Test] public void WaitingEnemyReceivesExistingNativeDamageWithoutPhaseRestart(){var source=Source();var b=ManualOperators(WaveBinding(source,HitPacket(source,true,false)));var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,Paths(b.Composition.Attack),10000);Time(s,"wait",1400);var waiting=source.Waves[0].Instances[2];var phase=Lives(s).Single(x=>(string)x["id"]==waiting.InstanceId);Assert.AreEqual("WaitingSocket",(string)phase["phase"]);long started=(long)phase["phaseStarted"];var hit=s.ApplyWaveBasic("waiting-hit","op_mira",waiting.InstanceId,1);Assert.AreEqual(1,hit.Hits.Count);Assert.Less(s.Hp(waiting.InstanceId),(int)waiting.Hp);Assert.AreEqual("WaitingSocket",(string)Lives(s).Single(x=>(string)x["id"]==waiting.InstanceId)["phase"]);Assert.AreEqual(started,(long)Lives(s).Single(x=>(string)x["id"]==waiting.InstanceId)["phaseStarted"]);}
  [Test] public void ExistingClimbingBuffUsesImpactPhaseAndEndsAtRoof(){var source=Source();var b=ManualOperators(WaveBinding(source,HitPacket(source,true,false),null,"BCB04"));var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,Paths(b.Composition.Attack),10000);var first=source.Waves[0].Instances[0];Time(s,"approach",1399);var approach=s.ApplyWaveBasic("approach-hit","op_mira",first.InstanceId,1).Hits.Single();Time(s,"climb",1800);var climb=s.ApplyWaveBasic("climb-hit","op_mira",first.InstanceId,1).Hits.Single();Assert.Greater((long)climb.BuffSource["damageBps"],(long)approach.BuffSource["damageBps"]);Time(s,"roof",2201);var second=source.Waves[0].Instances[1];Assert.AreEqual("Rooftop",(string)Lives(s).Single(x=>(string)x["id"]==second.InstanceId)["phase"]);var roof=s.ApplyWaveBasic("roof-hit","op_mira",second.InstanceId,1).Hits.Single();Assert.AreEqual((long)approach.BuffSource["damageBps"],(long)roof.BuffSource["damageBps"]);}
  [Test] public void UnknownProjectileBlocksEvenEmptyArenaWithFutureWavePlanned(){var source=Source();var p=HitPacket(source,true,true);p["stepTimeSpanTicks"]=100000;foreach(var g in ((JArray)p["geometry"]).Where(x=>(string)x["sourceId"]=="op_mira"))g["observedTick"]=1000;var local=LocalBoundaryAttackProfile(p);var b=WaveBinding(source,p,local);var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,Paths(b.Composition.Attack),10000);for(int i=0;i<10&&!source.Waves[0].Instances.All(x=>s.Hp(x.InstanceId)==0);i++)Time(s,"batch"+i,10000);Assert.IsTrue(source.Waves[0].Instances.All(x=>s.Hp(x.InstanceId)==0));Assert.AreEqual(0,Lives(s).Count(x=>(bool)x["registered"]));Assert.IsTrue((bool)s.Capture()["waveEntry"]["unknownProjectile"]);Assert.AreEqual(0,(long)s.Capture()["waveEntry"]["gapUntil"]);Assert.AreEqual("RUNNING",s.Outcome);Assert.IsTrue(source.Waves[1].Instances.All(x=>s.Hp(x.InstanceId)==(int)x.Hp));}
  [TestCase(0,4)][TestCase(1,6)][TestCase(2,8)] public void NativeCapAndSaturatedOpportunitiesPreservePlannedHp(int index,int cap){var source=Source(index);var binding=WaveBinding(source);var s=BDirectAttackBasicLoop.CreateWaveRuntime(binding,source,null,10000);Time(s,"long",6000);Assert.AreEqual(cap,Lives(s).Count(x=>(bool)x["registered"]));Assert.AreEqual("RUNNING",s.Outcome);foreach(var x in source.Waves.SelectMany(w=>w.Instances))Assert.AreEqual((int)x.Hp,s.Hp(x.InstanceId));Assert.IsFalse(s.OrdinaryRuntimeGeometrySupported);}
  [Test] public void MissingGeometryCannotBecomeRoofOrCreateEnemyDamage(){var source=Source();var s=BDirectAttackBasicLoop.CreateWaveRuntime(WaveBinding(source),source,null,10000);Time(s,"long",6000);Assert.AreEqual(0,((JArray)s.Capture()["results"][0]["hits"]).Count);Assert.IsTrue(Lives(s).Where(x=>(bool)x["registered"]).All(x=>(string)x["phase"]=="GeometryPending"));Assert.IsFalse((bool)s.Capture()["boarding"]["runtimeGeometrySupported"]);}
  [Test] public void TwoSocketsWaitAndRoofFloorPreservesNativeCooldown(){var source=Source();var b=WaveBinding(source);var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,Paths(b.Composition.Attack),10000);Time(s,"entrance",600);Assert.IsTrue(Lives(s).Take(4).All(x=>(string)x["phase"]=="Approach"));Time(s,"approach",800);Assert.AreEqual(2,Lives(s).Count(x=>(string)x["phase"]=="Attached"));Assert.AreEqual(2,Lives(s).Count(x=>(string)x["phase"]=="WaitingSocket"));Time(s,"climb",200);Assert.AreEqual(2,Lives(s).Count(x=>(string)x["phase"]=="Climbing"));Time(s,"roof",1800);Assert.AreEqual(2,Lives(s).Count(x=>(string)x["phase"]=="Rooftop"));Assert.AreEqual(2,Lives(s).Count(x=>(string)x["phase"]=="Attached"));foreach(var x in source.Waves[0].Instances.Take(2)){long floor=x.DefinitionId=="enemy_raider_scout"?5000:5400;Assert.GreaterOrEqual((long)s.Capture()["state"]["direct"]["next"][x.InstanceId],floor);}}
  [Test] public void WaveRestoreAndPauseDebtAreExactAndTamperingIsRejected(){var source=Source();var b=WaveBinding(source);var paths=Paths(b.Composition.Attack);var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,paths,10000);s.Advance("credit",20000000,500);s.SetPaused("pause",true);Time(s,"paused",1000);Assert.AreEqual(500,s.Tick);var cache=s.Capture();var restored=BDirectAttackBasicLoop.RestoreWaveRuntime(cache,BDirectAttackInput.Digest(cache),b,source,paths,10000);s.SetPaused("resume",false);restored.SetPaused("resume",false);s.Advance("debt",0,2000);restored.Advance("debt",0,2000);Assert.IsTrue(JToken.DeepEquals(s.Capture(),restored.Capture()));cache["boarding"]["lives"][0]["generation"]=99;Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.RestoreWaveRuntime(cache,BDirectAttackInput.Digest(cache),b,source,paths,10000));}
  [Test] public void GunnerLaunchCannotBecomeInstantDamageOrKnownZeroResidual(){var source=Source(2);Assert.AreEqual("enemy_spike_cart_gunner",source.Waves[0].Instances[0].DefinitionId);var p=HitPacket(source,false,true);p["stepTimeSpanTicks"]=100000;var b=WaveBinding(source,p);var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,Paths(b.Composition.Attack),10000);s.Advance("earliest",53990000,539);Assert.IsFalse((bool)s.Capture()["waveEntry"]["unknownProjectile"]);var result=s.Advance("launch",6100000,61);Assert.IsTrue((bool)s.Capture()["waveEntry"]["unknownProjectile"]);Assert.IsTrue(result.Hits.All(h=>source.Waves.SelectMany(w=>w.Instances).Single(x=>x.InstanceId==h.Attack.SourceId).DefinitionId!="enemy_spike_cart_gunner"));Assert.AreEqual("RUNNING",s.Outcome);}
  [Test] public void PathProofRejectsDisconnectedSocketsAndForeignInput(){var source=Source();var b=WaveBinding(source);var input=b.Composition.Attack;var paths=Paths(input);var bad=paths.Capture();bad["carriages"][0]["right"]["socketId"]="left";Assert.Throws<ArgumentException>(()=>BWaveBoardingLocalPaths.Read(bad,BDirectAttackInput.Digest(bad),input));bad=paths.Capture();bad["carriages"][0]["left"]["climbPathMm"][0][0]=99;Assert.Throws<ArgumentException>(()=>BWaveBoardingLocalPaths.Read(bad,BDirectAttackInput.Digest(bad),input));var alternate=WavePacket(source);alternate["stepTimeSpanTicks"]=100000;var other=WaveBinding(source,alternate);Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.CreateWaveRuntime(other,source,paths,10000));}
  [Test] public void WaveGeometryCannotExpandApprovedEnemyRange(){var source=Source();var p=HitPacket(source,false,true);var scout=source.Waves[0].Instances.First(x=>x.DefinitionId=="enemy_raider_scout");((JArray)p["geometry"]).Single(x=>(string)x["sourceId"]==scout.InstanceId)["maximumDistanceMm"]=1801;Assert.Throws<ArgumentException>(()=>ReadWave(p,source));}
  [Test] public void NativeJournalFailureAfterEarlierImpactsNeverPublishesWaveState(){var source=Source();var p=HitPacket(source,true,false);p["stepTimeSpanTicks"]=100000;var local=LocalBoundaryAttackProfile(p);var b=WaveBinding(source,p,local);var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,Paths(b.Composition.Attack),60);var before=s.Capture();Assert.Catch(()=>s.Advance("overflow",1000000000,10000));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void WaveCannotOverrideDerivedAdmissionOrPublishFailedNativeGeneration(){var source=Source();var b=WaveBinding(source,HitPacket(source,true,false));var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,Paths(b.Composition.Attack),10000);var before=s.Capture();Assert.Throws<ArgumentException>(()=>s.RecordEnemyAdmissionState("override",source.Waves[0].Instances[0].InstanceId,1,0,0,true,0));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));Assert.Throws<ArgumentException>(()=>s.ApplyWaveBasic("generation","op_mira",source.Waves[0].Instances[0].InstanceId,999));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void SameSimulationTimePartitionProducesSameLifetimeAndCooldown(){var source=Source();var p=WavePacket(source);p["stepTimeSpanTicks"]=100000;var b=WaveBinding(source,p);var paths=Paths(b.Composition.Attack);var a=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,paths,10000);var z=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,paths,10000);Time(a,"all",6000);Time(z,"first",1300);Time(z,"second",4700);Assert.AreEqual(a.Tick,z.Tick);foreach(string key in new[]{"boarding","waveEntry","enemyTiming"})Assert.IsTrue(JToken.DeepEquals(a.Capture()[key],z.Capture()[key]),key);Assert.IsTrue(JToken.DeepEquals(a.Capture()["state"]["direct"]["next"],z.Capture()["state"]["direct"]["next"]));}
  [Test] public void TwoNativeDeathsOnSameTickReturnSocketsOnceAndWaitForNextOpportunity(){var source=Source();var f=TwoOperatorFixture(source,true,true);var b=ManualOperators(f.binding);var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,f.paths,10000);Time(s,"attached",1400);var first=source.Waves[0].Instances[0];var second=source.Waves[0].Instances[1];Assert.AreEqual("Attached",(string)Lives(s).Single(x=>(string)x["id"]==first.InstanceId)["phase"]);s.ApplyWaveBasic("mira-kill","op_mira",first.InstanceId,1);s.ApplyWaveBasic("eve-kill","op_eve",second.InstanceId,1);Assert.AreEqual(0,s.Hp(first.InstanceId));Assert.AreEqual(0,s.Hp(second.InstanceId));Assert.AreEqual(2,Lives(s).Count(x=>(bool)x["registered"]));var events=(JArray)s.Capture()["boarding"]["events"];Assert.AreEqual(2,events.Count(e=>(string)e["kind"]=="SOCKET_RETURN_DEATH"&&(long)e["tick"]==140));Assert.AreEqual(4,(int)s.Capture()["waveEntry"]["cursor"]);Time(s,"before-opportunity",1170);Assert.AreEqual(4,(int)s.Capture()["waveEntry"]["cursor"]);Time(s,"opportunity",10);Assert.AreEqual(6,(int)s.Capture()["waveEntry"]["cursor"]);Assert.AreEqual(4,Lives(s).Count(x=>(bool)x["registered"]));}
  [Test] public void DownedOperatorDoesNotTeleportEntrantsOrClearUnspawnedPlan(){var source=Source();var p=HitPacket(source,false,true);p["stepTimeSpanTicks"]=100000;((JArray)p["entities"]).Single(x=>(string)x["id"]=="op_mira")["maxHp"]=1;var local=(JObject)Private("Owned");((JArray)local["operators"]).Single(x=>(string)x["operatorId"]=="op_mira")["permanentStats"]["maxHp"]=1;var b=WaveBinding(source,p,local);var s=BDirectAttackBasicLoop.CreateWaveRuntime(b,source,Paths(b.Composition.Attack),10000);Time(s,"down",10000);Assert.AreEqual(0,s.Hp("op_mira"));Assert.AreEqual("RUNNING",s.Outcome);Assert.IsTrue(Lives(s).Where(x=>(bool)x["registered"]).All(x=>(int)x["slot"]==0));Assert.AreEqual(4,(int)s.Capture()["waveEntry"]["cursor"]);Assert.IsTrue(Lives(s).Any(x=>(string)x["phase"]=="Planned"));}
  [Test] public void DestinationReadsNativeLivingOperatorEvenAfterCarriageBreak(){var old=(JObject)Private("Packet",1);((JArray)old["entities"]).Single(x=>(string)x["id"]=="car0")["maxHp"]=1;var legacy=(BDirectAttackBuffBinding)Private("Binding",old,"BCB01",5,"ENEMY");var native=new BDirectAttackBuffSession(legacy,1000);native.ApplyBasicImpact("break","enemy","car0",0);Assert.AreEqual(0,native.Hp("car0"));Assert.Greater(native.Hp("op_mira"),0);var source=Source();var b=WaveBinding(source);var type=typeof(BDirectAttackBasicLoop).Assembly.GetType("LastRail.Battle.BEnemyBoardingOwner");var board=Activator.CreateInstance(type,BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{source,b.Composition.Attack,BWaveBoardingPolicy.ForDepth(1),null},null);Assert.AreEqual(0,type.GetMethod("Destination",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(board,new object[]{native}));}
